mapper.select:
select archive_id, archive_code, title, archive_status from arc_archive where del_flag = '0' and archive_status in ('SUBMITTED','ARCHIVED')
and (title like concat('%',#{keyword},'%') or archive_code like concat('%',#{keyword},'%'))
order by create_time desc limit #{limit}

mapper.update:
update arc_borrow
set borrow_status = #{to}, update_by = #{operator}, update_time = now(), version = version + 1
where borrow_id = #{borrowId} and borrow_status = #{from}
